  "settings.sleepTabs": { area: "layout", what: "SettingsPanel · Performance · Unload hidden tabs after: a file viewer or Files (Project) tab hidden that long unmounts and reloads where it was when shown (unsaved edits/marks, a build or playing media hold it); a viewer popped out is unloaded in the main window at once. Terminal kinds (S10): a shell/agent tab hidden that long unmounts its xterm while its program keeps running; switching back re-attaches and shows the recent output (no respawn, no retyped prompt, \"[process exited]\" if it ended meanwhile); closing it while unloaded kills the program; scheduled/phone prompts still reach a sleeping agent; Host sessions and tabs shown in a popout, the root console or a docked agent column never unload" },
  "tabHoverCard.shellLaunch": { area: "layout", what: "Tab hover card · a shell tab Tabtivity opened shows what it was started with: \"program\" (the launched program and its args, e.g. an install's bash or a script's interpreter) and \"command\" (the line it typed into the shell, e.g. a Python Run, a SLURM log's tail -F); a plain shell opened from + shows neither; long commands wrap" },
  "tabHoverCard.agentFeatures": { area: "layout", what: "Tab hover card · an agent tab lists what it was handed: \"sandbox\" (inside the agent sandbox / Host session — no sandbox / none on Windows), \"MCP\" (Tabtivity's servers it holds a token for, e.g. the help and git servers, then your own servers from its scope's CLI config), \"skills\" (names from the scope home's skills folder, +N more past six) and \"API key\" when a stored key reaches it through the proxy; a remote or container agent shows none of these rows" },
  "tabCost.hover": { area: "layout", what: "Tab hover card · memory row: a shell/agent tab shows an estimate with its scrollback rows of the cap (\"Unloaded — the program keeps running\" while asleep, \"Not drawn yet\" before first shown, \"Shown in a pop-out window\" when popped out); a PDF (or TeX workspace) tab shows pages and file size, \"Unloaded — reloads when shown\" after its hidden release; other kinds show no row; never 0 B" },
  "settings.shellScrollback": { area: "layout", what: "SettingsPanel · Power & performance · Shell scrollback: a new shell tab (and the connection dialogs' terminals) keeps 2,000 lines by default, 1,000/5,000/10,000 when chosen; an agent tab always keeps 5,000; changing it applies to open shells at once (lowering it drops their oldest lines) with no restart, no respawn and no wake of a sleeping tab; the tab hover card's \"of N lines\" shows the new cap" },
  "settings.tabCosts": { area: "layout", what: "SettingsPanel · Power & performance · What open tabs hold: tabs largest estimate first, Show (current project) jumps to the tab and closes Settings, Close closes it, Refresh re-reads; tabs with nothing loaded collapse into a count line, PDFs outside a tab into one line. Also the loaded-PDF toast: at 8 PDFs loaded at once in the main window (not within 2 min of start) one self-dismissing notice; none again until the count drops to 5" },
  "settings.debugNoExperiments": { area: "layout", what: "SettingsPanel · Experimental · Debug mode no longer turns experiments on: on a profile that had Debug mode on before the update, the first launch ticks every experiment it was showing (not the WebGL renderer) and they stay on, browser tabs and the mail button included; a ticked experiment unticked stays off when Debug is toggled off and on; on a profile with Debug off, turning Debug on shows no experiment" },
