  "mobile-every-project-type": { area: "mobile", what: "Mobile access for every project type · the side panel's phone button, its picker head and the Settings → Mobile project rows now offer remote, container and VM projects too, with a line on what the phone reaches (remote: its local agents and the mirror; container/VM: listed, tabs in a later version)" },
  "mobile.deviceSections": { area: "mobile", what: "Settings → Mobile → Paired devices: per-phone To-do / Calendar / Mail buttons · a hidden section leaves that phone's tab bar, its routes answer section_hidden, its alert rows drop, and a phone without Calendar gets no reminder push" },
  "mobile.deviceProjects": { area: "mobile", what: "Settings → Mobile → Paired devices: per-phone project/box list · Disconnect takes that phone off the scope (an All-phones scope becomes the other paired phones; the last phone turns access off), Add project ▾ opens one for that phone (an off scope turns on for it alone)" },
  "mobile.signIn": { area: "mobile", what: "Terminal · Agent sign-in from the phone: notice + sheet for the CLI's login link (device code, paste-back code, localhost address relayed by the desktop), Status sheet Sign in button", tested: "2026-10-01" },
  "mobile.pair.singleScreen": { area: "mobile", what: "First phone connection · pairing code and local PIN are entered together; one tap pairs, sets the lock and opens the workspace" },
  "mobile.signIn.tab": { area: "mobile", what: "Project ＋ → Sign in to an agent (each CLI's login state, Sign in / other way in) and an agent tab's \"needs you to sign in\" notice: a sign-in tab running the CLI's own login command (Claude auth login, Codex login --device-auth, Copilot login --device-code, Cursor login, …), a step-by-step sheet with copy-and-open, one-tap Paste, Signed in ✓ and Start again", tested: "2026-10-01" },
  "mobile.signIn.apiBudgetReached": { area: "mobile", what: "Project ＋ → Sign in to an agent: a CLI on a desktop-stored API key whose monthly budget is spent (or has no limit) reads \"API budget reached\" instead of \"Uses an API key\"" },
