  "mobile.add.camera": { area: "mobile", what: "Terminal · Composer ＋ opens an attach tray of round tiles (Camera, Gallery, Files, Desktop, Project file); Camera opens the phone's camera at once and the photo lands in the message like any picked file; on an iPhone/iPad Files no longer greys out non-media files" },
  "mobile.composer.autoGrow": { area: "mobile", what: "Terminal · Composer grows line by line with a long draft (up to about a third of the screen, then scrolls) and drops back to one line when emptied or sent", tested: "2026-09-28" },
  "mobile.composer.penWriting": { area: "mobile", what: "Terminal · Composer on a pen device (iPad Pencil, S Pen): once the pen has touched or hovered over the app, the message field opens about four lines tall, and handwriting over it turns into text (iPad Scribble)" },
